import sys, json
sys.path.insert(0,'/workspace/dev')
import harness; harness.setup_env()
def build(rows):
    return {'capacity': {'range': 1, 'exact': 1},
            'releases': [{'id': 'm', 'classes': 1, 'width': 2, 'eps': [1, 1], 'ratio': [0, 1],
                          'threshold': [1, 1], 'mode': 'range', 'packet_limit': 2, 'idle_us': 0,
                          'discovery': [{'class': 0,
                                         'values': [1600, 1601, 1700, 1701, 1702,
                                                    1602, 1603, 1703, 1704, 1705],
                                         'activation': [1000, 1000, 0, 0, 0, 1000, 1000, 0, 0, 0]}
                                        for _ in range(rows)],
                          'train': [{'class': 0, 'values': [1, 2]}],
                          'validation': [{'class': 0, 'values': [1, 2]}]}],
            'blocks': []}
for rows, invalid in ((2048, False), (2049, True)):
    out = harness.answer(json.dumps(build(rows), separators=(',', ':')).encode())
    bad = out.get('error') == 'invalid_request'
    print('rows', rows, 'fragments', out['catalog'][0]['fragments'][:2] if not bad else '-',
          'rejected' if bad else 'accepted', 'expected', 'rejected' if invalid else 'accepted',
          'OK' if bad == invalid else 'PROBLEM')
PYEOF
